// Package request defines the request identity type and validation.
package request

import "strings"

// ErrInvalidRequest is returned when a request lacks a valid identity.
var ErrInvalidRequest = &invalidRequestError{}

type invalidRequestError struct{}

func (*invalidRequestError) Error() string { return "invalid request: empty request ID" }

// Request carries the identity and kind for an operation.
type Request struct {
	RequestID string
	Kind      string
}

// Validate checks that the request has a non-empty identity.
func (r Request) Validate() error {
	if r.RequestID == "" {
		return ErrInvalidRequest
	}
	return nil
}

// Normalize returns the normalized form of kind by lowercasing and trimming whitespace.
func Normalize(kind string) string {
	return normalizeKind(kind)
}

// normalizeKind lowercases and trims whitespace from kind.
func normalizeKind(kind string) string {
	return strings.TrimSpace(strings.ToLower(kind))
}

// Package response defines the response type with its own identity separate from request identity.
package response

// Response carries a response identity and the correlated request identity.
type Response struct {
	ID        string
	RequestID string
}

// CorrelationID returns the response's own identity.
func (r Response) CorrelationID() string {
	return r.ID
}

// Index finds a response by its own ID in the slice.
func Index(s []Response, id string) (Response, bool) {
	for _, r := range s {
		if r.ID == id {
			return r, true
		}
	}
	return Response{}, false
}

// AuditRow carries an independent identity for audit purposes.
type AuditRow struct {
	ID string
}

// SameID returns true when two independent identities match.
func SameID(r Response, a AuditRow) bool {
	return r.ID == a.ID
}

// Package review defines the review type with its own identity separate from request identity.
package review

// Review carries a review identity and the correlated request identity.
type Review struct {
	ID        string
	RequestID string
}

// Key returns the review's own identity.
func (r Review) Key() string {
	return r.ID
}

// ByID finds a review by its own ID in the slice.
func ByID(s []Review, id string) (Review, bool) {
	for _, r := range s {
		if r.ID == id {
			return r, true
		}
	}
	return Review{}, false
}

// Package correlation collects identities from distinct types.
package correlation

import (
	"example.com/identityservice/request"
	"example.com/identityservice/response"
	"example.com/identityservice/review"
)

// IDs returns the identity strings from a request, response, and review.
func IDs(r request.Request, resp response.Response, rev review.Review) []string {
	return []string{r.RequestID, resp.ID, rev.ID}
}

// Package gateway handles request submission through a client.
package gateway

import (
	"errors"
	"example.com/identityservice/request"
	"example.com/identityservice/response"
)

// ResponseClient sends requests and receives responses.
type ResponseClient interface {
	Send(request.Request) (response.Response, error)
}

// Handler manages request submission.
type Handler struct {
	client ResponseClient
}

// Submit sends a request through the client and validates the response.
func (h Handler) Submit(req request.Request) (response.Response, error) {
	if err := req.Validate(); err != nil {
		return response.Response{}, err
	}
	resp, err := h.client.Send(req)
	if err != nil {
		return response.Response{}, err
	}
	if resp.ID == "" {
		return response.Response{}, errors.New("response missing own identity")
	}
	return resp, nil
}

// Package queue provides queue operations keyed by request identity.
package queue

import "example.com/identityservice/request"

// Entry is a queue entry keyed by a string and carrying a request.
type Entry struct {
	Key     string
	Value   request.Request
}

// Contains reports whether the queue contains an entry matching the request identity.
func Contains(entries []Entry, r request.Request) bool {
	for _, e := range entries {
		if e.Key == r.RequestID {
			return true
		}
	}
	return false
}

// BatchKeys returns the request identities for a batch of requests.
func BatchKeys(reqs []request.Request) []string {
	keys := make([]string, len(reqs))
	for i, r := range reqs {
		keys[i] = r.RequestID
	}
	return keys
}

// Package reporting groups rows by request identity.
package reporting

import "example.com/identityservice/request"

// Row is a reporting row associated with a request.
type Row struct {
	Request request.Request
	Label   string
}

// Group groups rows by the request identity.
func Group(rows []Row) map[string][]Row {
	groups := make(map[string][]Row)
	for _, r := range rows {
		groups[r.Request.RequestID] = append(groups[r.Request.RequestID], r)
	}
	return groups
}

// Package notifications builds destinations from request identity.
package notifications

import "example.com/identityservice/request"

// Notice is a notification associated with a request.
type Notice struct {
	Request request.Request
}

// DestinationFor returns the notification destination for a request.
func DestinationFor(r request.Request) string {
	return "request:" + r.RequestID
}

// IDs returns the request identities for a batch of notices.
func IDs(notices []Notice) []string {
	ids := make([]string, len(notices))
	for i, n := range notices {
		ids[i] = n.Request.RequestID
	}
	return ids
}

// Package scheduler filters jobs by request identity.
package scheduler

import "example.com/identityservice/request"

// Job is a scheduled job associated with a request.
type Job struct {
	Request request.Request
}

// Pending returns jobs matching the request identity.
func Pending(jobs []Job, r request.Request) []Job {
	var result []Job
	for _, j := range jobs {
		if j.Request.RequestID == r.RequestID {
			result = append(result, j)
		}
	}
	return result
}

// Package storage provides storage operations keyed by record identity.
package storage

import "example.com/identityservice/request"

// RequestRecord is a storage record with its own identity and an embedded request.
type RequestRecord struct {
	ID      string
	Request request.Request
}

// Lookup finds a record by its own ID in the slice.
func Lookup(records []RequestRecord, id string) (RequestRecord, bool) {
	for _, r := range records {
		if r.ID == id {
			return r, true
		}
	}
	return RequestRecord{}, false
}

